var rollup_browserExports = rollup_browser.exports;

const resolvePath = (path) => {
    if (pathPolyfillExports.isAbsolute(path))
        return path;
    return pathPolyfillExports.join(process.cwd(), path);
};
var fluentToRollupfs = (fs) => ({
    async appendFile(path, data, options) {
        return fs.writeFileSync(resolvePath(path), data);
    },
    async copyFile(source, destination, mode) {
        return fs.copyFileSync(source, destination);
    },
    async mkdir(path, options) {
        if (options?.recursive) {
            fs.mkdirSync(resolvePath(path), { recursive: true });
        }
        else {
            fs.mkdirSync(resolvePath(path));
        }
    },
    async mkdtemp(prefix) {
        const random = await crypto.randomUUID();
        const path = `${prefix}${random}`;
        this.mkdir(resolvePath(path));
        return path;
    },
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    async readdir(path, options) {
        return fs.readdirSync(resolvePath(path), options);
    },
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    async readFile(path, options) {
        if (options?.encoding) {
            return fs.readFileSync(resolvePath(path), {
                encoding: "utf-8",
            });
        }
        return fs.readFileSync(resolvePath(path));
    },
    async realpath(path) {
        return fs.realpathSync(resolvePath(path));
    },
    async rename(oldPath, newPath) {
        return fs.renameSync(resolvePath(oldPath), resolvePath(newPath));
    },
    async rmdir(path, options) {
        return fs.rmSync(resolvePath(path), options);
    },
    async stat(path) {
        return fs.statSync(resolvePath(path));
    },
    async lstat(path) {
        return fs.lstatSync(resolvePath(path));
    },
    async unlink(path) {
        return;
    },
    async writeFile(path, data, options) {
        if (options?.encoding) {
            fs.writeFileSync(resolvePath(path), data, { encoding: "utf-8" });
        }
        else {
            fs.writeFileSync(resolvePath(path), data);
        }
    },
});

/**
 * Checks whether the input looks like a glob pattern targeting HTML or XML
 * files (e.g. "src/client/**\/*.html"). When true, the wrapper resolves the
 * glob and runs one rollup build per file to prevent code-splitting.
 */
const isHtmlGlobInput = (input) => typeof input === "string" &&
    (input.includes("*") || input.includes("?")) &&
    (input.endsWith(".html") || input.endsWith(".xml"));
