    if (isBrowserOrWorkerEnvironment()) {
        const existing = [];
        if (Array.isArray(options.plugins)) {
            existing.push(...options.plugins);
        }
        else if (options.plugins) {
            existing.push(options.plugins);
        }
        return { ...options, plugins: [...existing, webFsLoader()] };
    }
